import unicodedata


def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif ch in (' ', '-', '_'):
            out.append('-')
    # collapse consecutive dashes
    result = []
    for ch in out:
        if ch == '-' and result and result[-1] == '-':
            continue
        result.append(ch)
    return ''.join(result).strip('-')

import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose diacritics and strip combining marks
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    # Replace any non-alphanumeric char with a hyphen, then collapse runs
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    parts = [p for p in ''.join(out).split('-') if p]
    return '-'.join(parts)

