import unicodedata


def slugify(s):
    # Transliterate Unicode letters to their closest ASCII equivalents
    # by decomposing characters and dropping the combining diacritical marks.
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            # Collapse any run of non-alphanumeric characters into a single '-'.
            if out and out[-1] != '-':
                out.append('-')
    # Strip any trailing separator left over from a trailing non-alnum char.
    while out and out[-1] == '-':
        out.pop()
    return ''.join(out)
